export function NumbersAnimatedDemo({exampleId,frameIndex,visual,paused=false}:NumbersAnimatedDemoProps){
 const kind=visual.model?.kind??'',s=visual.state?.renderFrame??frameIndex,help=visual.helpMode===true;
 let scene:ReactNode;
 if(kind==='fraction-refinement')scene=<Fractions s={s} help={help}/>;
 else if(kind==='long-division-cycle')scene=<Decimal s={s} help={help}/>;
 else if(kind==='nested-exact-intervals')scene=<Intervals s={s} help={help}/>;
 else if(kind==='branching-multiplication')scene=<Growth s={s} help={help}/>;
 else if(kind==='factor-concatenation'||kind==='factor-group-repetition')scene=<Factors s={s} repeat={kind==='factor-group-repetition'} help={help}/>;
 else if(kind==='reciprocal-exponent-track')scene=<Reciprocal s={help?Math.min(s,2)+1:s}/>;
 else if(['positive-root-square','root-power-reciprocal','equivalent-root-routes'].includes(kind))scene=<Root s={s} kind={kind} help={help}/>;
 else if(['real-exponent-brackets','power-log-inverse','decreasing-power-log'].includes(kind))scene=<Axes s={s} kind={kind} help={help}/>;
 else if(['exponent-path-addition','log-quotient-power','change-base-units','false-log-sum'].includes(kind))scene=<LogLaws s={s} kind={kind}/>;
 else if(kind==='log-exponent-interval')scene=<LogBracket s={s} help={help}/>;
 else if(kind==='additive-error-bound')scene=<ErrorBound s={s} help={help}/>;
 else if(kind==='round-order')scene=<RoundOrder s={s} help={help}/>;
 else if(kind==='exact-rounded-strips')scene=<Rounding s={s} help={help}/>;
 else if(['indexed-accumulation','formula-summands','empty-sum'].includes(kind))scene=<Sums s={s} kind={kind} help={help}/>;
 else if(kind==='dummy-index-rename')scene=<Dummy s={s} help={help}/>;
 else if(kind==='reindex-reverse')scene=<Reverse s={s} help={help}/>;
 else if(kind==='reindex-square-cards')scene=<Reindex s={s} kind={kind} help={help}/>;
 else if(kind==='arithmetic-gaps')scene=<ArithmeticGaps s={s} help={help}/>;
 else if(['arithmetic-pairing','signed-arithmetic-pairing'].includes(kind))scene=<Arithmetic s={s} kind={kind} help={help}/>;
 else if(kind==='geometric-shift')scene=<GeometricShift s={s} help={help}/>;
 else if(['geometric-signed-cancellation','geometric-unit-ratio','geometric-empty-boundaries'].includes(kind))scene=<Geometric s={s} kind={kind} help={help}/>;
 else scene=<T y={170}>No authored number model: {kind}</T>;
 if(help&&kind==='root-power-reciprocal')scene=<SmallRootReciprocal s={s}/>;
 if(help&&['real-exponent-brackets','power-log-inverse','decreasing-power-log'].includes(kind))scene=<SmallPowerMap s={s} kind={kind}/>;
 if(help&&['exponent-path-addition','log-quotient-power','change-base-units'].includes(kind))scene=<SmallLogLaw s={s} kind={kind}/>;
 return <svg ref={node=>bindNumbersMotion(node,`${exampleId}:${help}:${frameIndex}`,paused)} viewBox="0 0 640 400" role="img" aria-label={visual.state?.caption??kind} data-number-model={kind} data-frame={frameIndex} style={{width:'100%',height:'auto',display:'block',fontFamily:'inherit',color:'inherit'}}><title>{visual.state?.caption??kind}</title>{scene}</svg>;
}
